package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: ZFSD_PRICE_SIMULATION / {@code ZTSD_PS_ITEMS} / item 
 */
public class PricingCallDTOItem implements Serializable {

	private static final long serialVersionUID = -4323358688354232083L;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / ITM_NUMBER
	 */
	private String itemNumber;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / MATERIAL
	 */
	private String material;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / PLANT 
	 */
	private String plant;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / TARGET_QTY
	 */
	private String targetQty;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / TARGET_QU 
	 */
	private String targetQuantityUom;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / INCOTERMS1 
	 */
	private String incoterms;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / DIVISION
	 */
	private String division;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / SHIP_POINT 
	 */
	private String shippingPoint;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item / MAT_PR_GRP
	 */
	private String materialPricingGroup;

	public String getItemNumber() {
		return itemNumber;
	}

	public void setItemNumber(String itemNumber) {
		this.itemNumber = itemNumber;
	}

	public String getMaterial() {
		return material;
	}

	public void setMaterial(String material) {
		this.material = material;
	}

	public String getPlant() {
		return plant;
	}

	public void setPlant(String plant) {
		this.plant = plant;
	}

	public String getTargetQty() {
		return targetQty;
	}

	public void setTargetQty(String targetQty) {
		this.targetQty = targetQty;
	}

	public String getTargetQuantityUom() {
		return targetQuantityUom;
	}

	public void setTargetQuantityUom(String targetQuantityUom) {
		this.targetQuantityUom = targetQuantityUom;
	}

	public String getIncoterms() {
		return incoterms;
	}

	public void setIncoterms(String incoterms) {
		this.incoterms = incoterms;
	}

	public String getDivision() {
		return division;
	}

	public void setDivision(String division) {
		this.division = division;
	}

	public String getShippingPoint() {
		return shippingPoint;
	}

	public void setShippingPoint(String shippingPoint) {
		this.shippingPoint = shippingPoint;
	}

	public String getMaterialPricingGroup() {
		return materialPricingGroup;
	}

	public void setMaterialPricingGroup(String materialPricingGroup) {
		this.materialPricingGroup = materialPricingGroup;
	}

	@Override
	public String toString() {
		return "PricingCallDTOItem [itemNumber=" + itemNumber + ", material=" + material
				+ ", plant=" + plant + ", targetQty=" + targetQty + ", targetQuantityUom="
				+ targetQuantityUom + ", incoterms=" + incoterms + ", division=" + division
				+ ", shippingPoint=" + shippingPoint + ", materialPricingGroup="
				+ materialPricingGroup + "]";
	}

}